const applicantForm=document.getElementById('applicant-form');
if(applicantForm){
const serviceFields=document.getElementById('service-fields');
const serviceDefinitions={
'Saudi Employment Visa':['Saudi visa number','Visa issue date','Visa validity','Sponsor/kafeel name','Sponsor ID','Saudi company/employer','Job title/profession','Employment contract number','Wakala number','Musaned contract number','Saudi mission/consulate','Medical status','GAMCA/Wafid slip number','Medical centre','Medical expiry date','PCC status','Emigration status','Protector of Emigrants reference','Flight/travel date'],
'Wakala Service':['Employer/sponsor name','Employer ID','Visa number','Profession','Contract number','Contract date','Recruitment agency','Saudi service provider','Musaned status','Wakala authorization status','Attestation status'],
'Musaned Services':['Employer/sponsor name','Employer ID','Visa number','Profession','Contract number','Contract date','Recruitment agency','Saudi service provider','Musaned status','Wakala authorization status','Attestation status'],
'Saudi Umrah Visa':['Travel type','Group/reference number','Intended departure date','Intended return date','Duration','Makkah hotel','Madinah hotel','Arrival airport','Departure airport','Airline','Flight PNR','Mahram details','Relationship with Mahram','Saudi Umrah operator','Package name','Vaccination status','Travel insurance status'],
'Kuwait Visa Services':['Kuwait visa type','Kuwait visa/reference number','Visa issue date','Visa validity','Sponsor name','Sponsor civil ID','Kuwait employer/company','Job title/profession','Work permit number','Work permit expiry','Medical status','PCC status','Kuwait Embassy submission status','Travel date'],
'Document Attestation':['Document type','Issuing institution','Issuing state/country','Destination country','Required authorities','Number of original documents','Courier required','Current attestation stage','Original document received date','Original document returned date'],
'Translation Services':['Source language','Target language','Document type','Number of pages','Certified translation required','Embassy format required','Delivery format','Required delivery date']};
const codeMap={'Saudi Employment Visa':'SAU','Wakala Service':'WKL','Musaned Services':'MUS','Saudi Umrah Visa':'UMR','Kuwait Visa Services':'KWT','Document Attestation':'ATT','Translation Services':'TRN'};
const inputType=label=>/date|travel|delivery/i.test(label)?'date':/number|pages|duration/i.test(label)?'number':'text';
const renderServiceFields=()=>{const service=document.getElementById('applicant-service').value;serviceFields.innerHTML='';serviceFields.hidden=!service;if(!service)return;const fieldset=document.createElement('fieldset');const legend=document.createElement('legend');legend.textContent=service+' details';fieldset.appendChild(legend);(serviceDefinitions[service]||[]).forEach(label=>{const wrapper=document.createElement('label');wrapper.textContent=label;const input=document.createElement('input');input.type=inputType(label);input.dataset.detail='service_'+label.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');wrapper.appendChild(input);fieldset.appendChild(wrapper)});serviceFields.appendChild(fieldset);};
const date=document.getElementById('applicant-date');if(date&&!date.value)date.value=new Date().toISOString().slice(0,10);
const service=document.getElementById('applicant-service');if(service)service.addEventListener('change',renderServiceFields);
const expiry=document.querySelector('[data-detail="passport_expiry_date"]');const expiryWarning=document.createElement('p');expiryWarning.id='passport-expiry-warning';expiryWarning.setAttribute('role','status');if(expiry)expiry.insertAdjacentElement('afterend',expiryWarning);if(expiry)expiry.addEventListener('change',()=>{const limit=new Date();limit.setMonth(limit.getMonth()+6);const value=new Date(expiry.value);expiryWarning.textContent=expiry.value&&value<=limit?'Warning: passport expires within six months.':'';});
applicantForm.addEventListener('reset',()=>{setTimeout(renderServiceFields,0)});
applicantForm.addEventListener('submit',async event=>{event.preventDefault();const message=document.getElementById('applicant-message');const selected=service.value;if(!selected){message.textContent='Select a service category.';return}const details={};applicantForm.querySelectorAll('[data-detail]').forEach(field=>{if(field.value)details[field.dataset.detail]=field.value});const consents={};applicantForm.querySelectorAll('[data-consent]').forEach(field=>{consents[field.dataset.consent]=field.checked});const reference=document.getElementById('applicant-reference');details.internal_notes=document.getElementById('applicant-notes').value;message.textContent='Saving applicant...';try{const response=await fetch('/api/applicants',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','X-CSRF-Token':window.crmCsrf||''},body:JSON.stringify({reference:reference.value,application_date:date.value,service:selected,status:document.getElementById('applicant-status').value,priority:document.getElementById('applicant-priority').value,assigned_staff:document.getElementById('applicant-assigned-staff').value,source:document.getElementById('applicant-source').value,full_name:document.getElementById('applicant-name').value,mobile:document.getElementById('applicant-mobile').value,email:document.getElementById('applicant-email').value,details,consents})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to save applicant');message.textContent=`Application ${result.reference} saved.`;applicantForm.reset();}catch(error){message.textContent=error.message;}});
renderServiceFields();
}
